insert into public.board_exam_questions (board, contest_name, career_name, exam_year, exam_date, exam_type, item_number, subject, support_text, stem, options, official_answer, needs_visual, legal_review_required, state, career_category, source_url, answer_key_url, review_note) values
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',1,'Língua Portuguesa',null,'Em todas as opções abaixo há uma frase, da qual foi retirada uma informação implícita (uma inferência). Assinale a opção em que a inferência apontada está adequada à frase.','{"A": "Quando se é velho, é preciso ser mais ativo do que quando jovem / os velhos trabalham mais que os jovens, por isso precisam de energia.", "B": "Uma criança mimada nunca ama sua mãe / é indispensável saber educar os filhos.", "C": "Nunca faças hoje o que podes deixar para amanhã / a pressa é amiga da perfeição.", "D": "Em toda iniciativa, pensa bem aonde queres chegar / em toda atividade, a disciplina financeira é indispensável.", "E": "Morrer gloriosamente é melhor do que salvar-se / a disciplina militar ajuda bastante na trajetória da vida."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',2,'Língua Portuguesa',null,'Observe o texto a seguir. “Dvorak aproximou-se da entrada da caverna e procurou observar o seu interior. Havia alguns restos de fogueiras e ossos de animais espalhados. Nas paredes, alguns desenhos ininteligíveis, em cores pálidas. O teto mostrava alguns buracos por onde penetrava a luz do sol. Dvorak aprofundou-se na gruta e notou que ela era muito mais funda do que aparentava. Certamente o grupo que conduzia poderia proteger-se ali, já que havia uma só entrada e algumas saídas poderiam ser arranjadas”. Sobre os diferentes gêneros textuais presentes nesse segmento, é correto afirmar que','{"A": "os segmentos do texto mostram estruturação narrativa, com sua básica evolução cronológica.", "B": "o texto é integralmente descritivo, tendo por objeto os aspectos visuais do interior da caverna.", "C": "o texto, após um início narrativo, desvia para a estruturação descritiva, terminando com uma reflexão do personagem.", "D": "o texto, de caráter dissertativo-expositivo, tenta mostrar as dificuldades de encontrar-se um lugar seguro para morar, na época pré-histórica.", "E": "o segmento final do texto mostra que sua finalidade é argumentativa."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',3,'Língua Portuguesa',null,'Assinale a opção que exemplifica um gênero textual diferente dos demais.','{"A": "A ciência comete suicídio quando adota um credo.", "B": "Não é possível que exista uma moral científica; mas também não é possível que haja uma ciência imoral.", "C": "Conhecer é um ato. A ciência pertence, portanto, ao âmbito da moral.", "D": "Não devemos acreditar em tudo que nos contam.", "E": "Não há nenhum mal no átomo, apenas na alma dos homens."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',4,'Língua Portuguesa',null,'Há frases interrogativas que são na verdade afirmações, pois a resposta já está contida implicitamente na pergunta, como no seguinte caso:','{"A": "Onde você acha que eu moro?", "B": "Pode-me mostrar tua carteira, por favor?", "C": "Gostaria de comer sobremesa?", "D": "Quem pode dizer que dessa água eu não beberei?", "E": "Onde está o meu celular?"}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',5,'Língua Portuguesa',null,'Assinale a frase em que a preposição para tem valor semântico diferente do das demais frases.','{"A": "Eu gosto do trabalho. Ele me fascina. Posso sentar e olhar para ele por horas.", "B": "Os turistas caminharam para a catedral da cidade, famosa por suas pinturas.", "C": "Para o ministro, a luta contra as injustiças sociais deve ser o principal do programa presidencial.", "D": "A solução para resolver os problemas da pesquisa era ir para a biblioteca.", "E": "Um casal deve caminhar sempre para a mesma meta."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',6,'Língua Portuguesa',null,'Observe o início de uma descrição, em que alguns artigos estão destacados. “Um casal dirigia-se a um restaurante do centro da cidade para comemorar 20 anos de casados; o restaurante estava repleto, mas havia ainda algumas mesas disponíveis; logo que se sentaram numa delas, um garçom aproximou-se e entregou-lhes o cardápio”. Sobre um desses artigos, assinale a afirmativa correta.','{"A": "“Um casal” mostra o artigo indefinido para indicar nenhuma importância narrativa.", "B": "o termo “o restaurante” mostra o artigo definido por já haver sido citado anteriormente.", "C": "o elemento “um restaurante” mostra o artigo indefinido para mostrar que se trata de um restaurante qualquer, sem sofisticação.", "D": "“um garçom” mostra um emprego inadequado do artigo indefinido.", "E": "“o cardápio” traz um artigo definido por ser um elemento inesperado na situação narrada."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',7,'Língua Portuguesa',null,'Assinale a frase que é expressa sem qualquer redundância, ou seja, emprego desnecessário de palavras.','{"A": "Existe um só sucesso: ser capaz de viver a sua vida do seu próprio jeito.", "B": "A loja fora montada com esforço e sua primeira inauguração se daria brevemente.", "C": "Entre todas as nações foram os gregos aqueles que de forma mais bela sonharam o sonho da vida.", "D": "Quem é tão firme de caráter que não pode ser seduzido?", "E": "Os caçadores, em função do perigo, tinham conseguido um abrigo protegido contra as feras."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',8,'Língua Portuguesa',null,'Assinale a frase cujo tema é a própria linguagem.','{"A": "Uma casa é feita de tijolo e pedra. Um lar é feito apenas de amor.", "B": "O destino normal das novas verdades é começar como heresias e terminar como superstições.", "C": "Se um homem não descobriu nada pelo que morreria, não está pronto para viver.", "D": "Tantas cabeças, quantas sentenças: cada um tem o seu modo de ver.", "E": "O medo segue o crime e é seu castigo."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',9,'Língua Portuguesa',null,'O verbo ficar pode ser empregado como verbo de ligação, com o sentido de “mudança de estado”, equivalente a “tornar-se”. Assinale a frase que serve de exemplo para esse emprego.','{"A": "Nossos corpos são onde nós ficamos, nossos espíritos são o que nós somos.", "B": "Os homens não podem ficar parados no mesmo lugar.", "C": "Onde fica o bairro da Prainha nesta cidade?", "D": "Os livros mais caros ficam nas prateleiras mais altas.", "E": "A justiça pode ficar cega, mas tem dispositivos de escuta muito sofisticados."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',10,'Língua Portuguesa',null,'Assinale a frase em que houve troca indevida entre se não / senão.','{"A": "O único senão da prova era a presença de textos muito longos.", "B": "Só ocorrerá a prova de ciclismo se não chover.", "C": "Fará a prova senão ficará arrependido.", "D": "Comprará um carro novo se não tiver problemas econômicos.", "E": "Ninguém, se não ela, para fazer esse trabalho."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',11,'Língua Portuguesa',null,'Todas as frases abaixo são compostas de dois períodos. A ligação lógica entre eles que está corretamente identificada, é:','{"A": "Faz parte da natureza dos mortais pisar ainda mais em quem já caiu. / os dois períodos estão em comparação.", "B": "Quando se tem tudo para temer, não se deve temer nada. / o segundo período é a causa do primeiro.", "C": "Eu não podia esperar pelo sucesso. Assim eu fui em frente sem ele. / o segundo período é uma conclusão do primeiro.", "D": "A vitória tem mil pais, mas a derrota é órfã. / o segundo período é cronologicamente posterior ao primeiro.", "E": "É melhor reinar no inferno do que servir no céu. / os períodos mostram uma relação de alternância."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',12,'Língua Portuguesa',null,'Assinale a frase em que houve troca indevida entre os parônimos colocados entre parênteses.','{"A": "Durante a conversa, ele não pôde deixar de fazer alusão à sua vida difícil (alusão / ilusão).", "B": "Ele evocou o heroísmo de seus comandados (evocou / invocou).", "C": "Diante daquela proposta inepta ele se limitou a bocejar (inepta / inapta).", "D": "A família perpetuava a memória do general, levando flores ao túmulo (perpetuava / perpetrava).", "E": "Pensando no futuro, o presidente se perdia em toda espécie de conjecturas (conjecturas / conjunturas)."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',13,'Língua Portuguesa',null,'Assinale a frase em que a expressão “é que” não mostra valor enfático, fazendo parte da estrutura sintática da frase.','{"A": "É o uniforme que faz esquecer aquele que o veste.", "B": "O hábito é que torna suportáveis até as coisas assustadoras.", "C": "A resposta é que todos devem colaborar.", "D": "A leitura é que nos torna mais cultos.", "E": "Não sabemos quando é que custa a vida."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',14,'Língua Portuguesa',null,'“O modo de se vestir é uma preocupação ridícula. Mas é muito ridículo para um homem não estar bem-vestido”. Sobre os componentes e o sentido desse pensamento de um estadista inglês, assinale a afirmação inadequada.','{"A": "O segmento “O modo de se vestir” mostra uma forma impessoal.", "B": "O segundo período funciona como argumento a favor do anterior.", "C": "Há uma contradição clara entre os dois períodos da frase.", "D": "O primeiro período do texto contém valor concessivo.", "E": "O segmento “não estar bem-vestido” equivale a “estar malvestido”."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',15,'Língua Portuguesa',null,'Assinale a frase em que a substituição do adjetivo sublinhado por uma oração adjetiva de valor semântico equivalente foi feita de forma adequada.','{"A": "O estilo é um modo muito simples de dizer coisas complicadas / que se complicam.", "B": "Serviço de emergência disponível só com 24 horas de antecedência / que se mostra disposto.", "C": "Meu animal favorito é o bife / que me favorece.", "D": "Moda, afinal, são apenas epidemias induzidas / que se induzem.", "E": "O poder não satisfaz, é como a droga que sempre exige doses maiores / que são mais perigosas."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',16,'Língua Portuguesa',null,'O adjetivo pode ser substituído por algumas outras palavras ou estruturas de valor equivalente. Assinale a frase em que a adjetivação relacionada ao substantivo sublinhado é realizada por meio de uma oração desenvolvida.','{"A": "O homem que se vende recebe sempre mais do que vale.", "B": "Os lutadores determinados a vencer são adversários difíceis.", "C": "Não confie nas mulheres de mais de quarenta anos.", "D": "Os livros escritos no Romantismo são sentimentais.", "E": "As frutas alimentam o corpo e a alma."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',17,'Língua Portuguesa',null,'Nas frases a seguir foram feitas modificações de modo a mudar o adjetivo da primeira frase para substantivo na segunda. Assinale a opção em que essa modificação é inadequada.','{"A": "A afirmação categórica / a categorização da afirmação.", "B": "Uma frase prolixa / a prolixidade da frase.", "C": "Uma apresentação brilhante / o brilhantismo da apresentação.", "D": "A cor opaca / a opacidade da cor.", "E": "O céu escuro / a escuridão do céu."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',18,'Língua Portuguesa',null,'“Um asno será sempre um asno, mesmo se o cobrires de ouro”. A ideia central dessa frase é a de que','{"A": "os animais nunca deixarão de ser animais.", "B": "os seres menores costumam apresentar-se como maiores.", "C": "a riqueza não deve ser desperdiçada.", "D": "muda-se a aparência, mas não a essência.", "E": "homens e animais se equiparam."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',19,'Língua Portuguesa',null,'As frases a seguir são construídas com dois segmentos. Assinale aquela em que não há oposição entre eles.','{"A": "Nos mortos eu sempre lia alguma coisa nova / e nos vivos ouvia repetir mil vezes mil coisas velhas.", "B": "Chama-se perseverança quando é por uma boa causa / e obstinação quando é por uma ruim.", "C": "O poder desgosta / quem não o possui.", "D": "O segredo de todo poder consiste em saber / que os outros são mais covardes do que nós.", "E": "Deus fez a fêmea / e os costureiros fizeram a mulher."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',20,'Língua Portuguesa',null,'Observe o seguinte segmento textual, de autoria do célebre escritor francês Diderot: “Além do equador um homem não é inglês, holandês, francês, espanhol ou português. Ele se apega somente àqueles princípios e preconceitos de seu país de origem que justificam a sua conduta ou servem de desculpa para esta. Ele rasteja quando está fraco; ele é violento quando forte; ele tem pressa para adquirir, pressa para desfrutar, e é capaz de todo crime que o conduza mais rapidamente a seus objetivos. Ele é um tigre doméstico que retorna à selva; a sede de sangue toma conta dele outra vez. É assim que todos os europeus, cada um deles indistintamente, têm se mostrado nos países do Novo Mundo. Um delírio coletivo toma conta deles – a sede de ouro”. Todas as opções a seguir trazem informações explícitas ou implícitas contidas nesse texto. Assinale a opção que mostra uma informação explícita.','{"A": "quando viajam para o Novo Mundo, todos os europeus pretendem enriquecer.", "B": "os europeus, quando no Novo Mundo, voltam a um estágio anterior primitivo, não respeitando as leis.", "C": "os europeus, culturalmente falando, são superiores aos povos do Novo Mundo.", "D": "os europeus, no Novo Mundo, apesar de diferentes países, se igualam em seu procedimento primitivo e ilegal.", "E": "os europeus procedem de forma irracional quando, no Novo Mundo, pretendem adquirir riqueza. Informática"}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',21,'Informática',null,'O Word 2019 e o Excel 2019 salvam seus arquivos em determinados formatos por padrão. Assinale as extensões que correspondem aos formatos de arquivo padrão para o Word 2019 e o Excel 2019, respectivamente.','{"A": ".doc .xls", "B": ".docx .xlsx", "C": ".odt .ods", "D": ".xls .txt", "E": ".xlsl .docx"}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',22,'Informática',null,'Um usuário do Windows em português tem instaladas e configuradas 3 impressoras, HP 3160, HP LaserJet Pro 400 e HP Deskjet Plus 6476, tendo definido a segunda delas como impressora padrão. Nesse cenário, e dado que há outras impressoras disponíveis, assinale a afirmativa correta.','{"A": "Somente será possível imprimir na impressora HP LaserJet Pro 400.", "B": "Para utilizar qualquer impressora que não a HP LaserJet Pro 400, o usuário deverá realizar o mesmo procedimento e alterar a impressora padrão.", "C": "Caso a impressora HP LaserJet Pro 400 seja removida, o usuário não conseguirá imprimir em outra impressora.", "D": "No envio de material para impressão, sem designação específica da impressora, a impressora HP LaserJet Pro 400 será selecionada automaticamente.", "E": "Para remover a impressora HP LaserJet Pro 400, o usuário deve, previamente, designar uma nova impressora padrão."}'::jsonb,'D',true,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',23,'Informática',null,'Considere o seguinte trecho de uma planilha MS Excel exibida no modo Mostrar Fórmulas (guia Fórmulas): A B C D 1 3 3 11 0 2 2 2 13 5 3 5 =MÉDIA(D1:D4) 15 =SOMA(A1:B2) 4 1 0 10 1 Dado que a coluna “C” foi selecionada e excluída completamente, assinale os valores exibidos nas células B3 e C3, respectivamente, depois dessa operação.','{"A": "10 e 4.", "B": "4 e 10.", "C": "4 e 15.", "D": "4 e 5.", "E": "5 e 4."}'::jsonb,'B',true,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',24,'Informática',null,'No Windows, há um conjunto de caracteres que não podem ser usados em nomes de pastas e arquivos. Faz parte dessa lista de caracteres inválidos o caractere','{"A": "-", "B": "$", "C": "(", "D": "*", "E": "_"}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',25,'Informática',null,'Avalie as afirmativas a seguir, a respeito do Pincel de Formatação (PF) do MS Word: I. Os tipos de fontes não são afetados pela aplicação do PF. II. Os tamanhos das fontes não são afetados pela aplicação do PF. III. O PF pode ser acionado pelo mouse, com um clique simples ou um clique duplo. Está correto o que se afirma em','{"A": "II e III, apenas.", "B": "I e II, apenas.", "C": "I, apenas.", "D": "II, apenas.", "E": "III, apenas. Legislação"}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',26,'Processo Legislativo',null,'Determinada Comissão da Assembleia Legislativa do Estado do Maranhão (ALEMA) terá de examinar uma proposição que veicula uma matéria em regime de prioridade. Assim, em regra, dita Comissão obedecerá ao seguinte prazo para exame dessa matéria:','{"A": "cinco dias.", "B": "oito dias.", "C": "dez dias.", "D": "quinze dias.", "E": "trinta dias."}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',27,'Processo Legislativo',null,'A iniciativa popular de lei é um mecanismo singular de participação da sociedade civil nos rumos do governo. Por isso, é prevista também no Regimento Interno da Assembleia Legislativa do Estado do Maranhão (ALEMA), o qual veicula algumas regras para a tramitação de tais projetos de iniciativa popular. Acerca desse tema e à luz do referido Regimento Interno, avalie se as afirmativas a seguir são falsas (F) ou verdadeiras (V): ( ) Será lícito a entidade da sociedade civil patrocinar a apresentação de projeto de lei de iniciativa popular, responsabilizando-se inclusive pela coleta das assinaturas. ( ) Projeto de lei de iniciativa popular pode versar sobre o plano de carreiras do Ministério Público Estadual. ( ) O projeto de lei de iniciativa popular deve ser subscrito por, no mínimo, um por cento do eleitorado estadual, distribuído por pelo menos dezoito por cento dos municípios, com não menos de três décimos por cento dos eleitores de cada um deles. As afirmativas são, respectivamente,','{"A": "V – V – V.", "B": "V – V – F.", "C": "V – F – V.", "D": "F – V – F.", "E": "F – F – F."}'::jsonb,'C',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',28,'Processo Legislativo',null,'A apreciação de Proposta de Emenda à Constituição do Estado do Maranhão está entre as atividades mais relevantes da Assembleia Legislativa do Estado do Maranhão (ALEMA) no exercício de seu poder constituinte decorrente. Acerca dessa competência no Regimento Interno da ALEMA, assinale a afirmativa correta.','{"A": "A proposta de Emenda à Constituição será submetida a três turnos de discussão e votação.", "B": "Será aprovada a proposta que obtiver, em todos os turnos de votação, o voto favorável da maioria absoluta dos membros da ALEMA, em votação nominal.", "C": "A matéria constante de proposta de Emenda à Constituição rejeitada ou havida por prejudicada pode ser objeto de nova proposta na mesma sessão legislativa se subscrita por maioria absoluta dos membros da ALEMA.", "D": "A Emenda à Constituição será promulgada pelo Presidente da ALEMA com o respectivo número de ordem e dela enviada cópia ao Governador do Estado e ao Presidente do Tribunal de Justiça.", "E": "A ALEMA apreciará proposta de Emenda à Constituição se for apresentada por mais da metade das Câmaras Municipais do Estado com a manifestação de cada uma delas, pela maioria relativa de seus membros."}'::jsonb,'E',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',29,'Processo Legislativo',null,'Em determinada sessão plenária da Assembleia Legislativa do Estado do Maranhão (ALEMA), estavam presentes, ocupando as bancadas, deputados estaduais, convidados do Presidente, ex- parlamentares e funcionários da ALEMA cujas funções estavam diretamente ligadas à sessão plenária. Um dos deputados estaduais inscrito como orador solicitou ao Presidente para falar sentado e de sua bancada. Acerca dessa sessão, de acordo com o Regimento Interno da ALEMA, é correto afirmar que','{"A": "convidados do Presidente podem participar de sessão da ALEMA ocupando as bancadas.", "B": "funcionários da ALEMA que estejam a exercer funções diretamente ligadas à sessão podem permanecer no Plenário e, havendo vagas, inclusive ocupar bancadas.", "C": "em razão de já terem ocupado o cargo público no passado, ex- parlamentares possuem a prerrogativa regimental de, estando presentes às sessões, ocuparem bancadas que estejam vagas.", "D": "o orador deverá falar obrigatoriamente da tribuna, e não de sua bancada.", "E": "o orador deverá falar obrigatoriamente de pé, e não sentado."}'::jsonb,'A',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',30,'Processo Legislativo',null,'José, servidor público da Assembleia Legislativa do Estado do Maranhão não reincidente em falta funcional, fez uma crítica ao Governador do Estado do Maranhão, com uso de palavras depreciativas, em determinado despacho em processo administrativo que estava sob sua condução. Sobre a conduta de José, à luz do Estatuto dos Servidores Públicos Civis do Estado do Maranhão, é correto afirmar que','{"A": "é lícito a José criticar autoridade pública em tal despacho, ainda que se utilize de palavras depreciativas, desde que seus atos não constituam crimes contra a honra.", "B": "José cometeu falta administrativa, sendo passível de punição com suspensão por até 15 (quinze) dias.", "C": "José cometeu falta administrativa, sendo passível de punição com multa correspondente a até 5 (cinco) dias de sua remuneração.", "D": "José cometeu falta administrativa, sendo passível de punição com pena de advertência por escrito.", "E": "José, por não ser reincidente, embora tenha cometido falta administrativa, é passível de punição com pena de advertência de forma oral. Conhecimentos Específicos"}'::jsonb,'D',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',31,'Direito Constitucional',null,'Em uma gincana jurídica, os dois grupos envolvidos deveriam indicar, na perspectiva prevalecente no direito brasileiro, as características do poder constituinte originário. O grupo Alfa argumentava se tratar de um poder de direito, de caráter permanente, e ao qual não são oponíveis direitos adquiridos. O grupo Beta, por sua vez, ressaltava a característica da iniciabilidade e o seu caráter incondicionado na perspectiva formal, sendo-lhe possível constitucionalizar o direito pré- constitucional de natureza infraconstitucional. Os jurados, ao avaliarem os posicionamentos dos dois grupos, concluíram corretamente que','{"A": "os dois grupos estão totalmente certos.", "B": "os dois grupos estão parcialmente certos.", "C": "o grupo Alfa está parcialmente certo e o grupo Beta, totalmente certo.", "D": "o grupo Alfa está totalmente errado e o grupo Beta, totalmente certo.", "E": "o grupo Alfa está totalmente certo e o grupo Beta, parcialmente certo."}'::jsonb,'C',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',32,'Direito Constitucional',null,'O Estado Alfa editou a Lei nº X, dispondo que os contratos de concessão em vigor, afetos à prestação do serviço local de gás canalizado, seriam prorrogados por dois anos. De acordo com a justificativa apresentada, foi esclarecido que o objetivo da prorrogação era o de viabilizar a realização de estudos destinados à alteração do modelo de exploração do serviço. À luz da sistemática constitucional vigente, é correto afirmar, em relação a essa narrativa, que a Lei nº X','{"A": "incursionou em temática afeta à competência legislativa municipal.", "B": "somente pode vir a ser apreciada pelo Supremo Tribunal Federal em sede de controle difuso de constitucionalidade.", "C": "somente pode ser objeto de arguição de descumprimento de preceito fundamental, por não se tratar de lei em sentido material.", "D": "não pode ser submetida ao controle concentrado de constitucionalidade perante o Supremo Tribunal Federal, por se tratar de lei de efeitos concretos.", "E": "pode ser objeto de ação direta de inconstitucionalidade, a ser ajuizada perante o Supremo Tribunal Federal, por se tratar de lei em sentido formal."}'::jsonb,'E',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',33,'Direito Constitucional',null,'Determinada associação de Municípios, em uma assembleia ordinária, constatou que, na quase totalidade dos entes municipais que a integravam, foi editada uma lei cujo teor era rotineiramente reproduzido em cada um desses entes. Aqueles que ainda não tinham editado lei similar, estavam prestes a fazê- lo, já que o processo legislativo se encontrava em curso. Apesar de a constitucionalidade dessas leis ser defendida por muitos juristas, diversos juízes e tribunais estavam se negando a aplicá-las, sob o argumento de incompetência dos Municípios para legislar sobre a matéria. Isto ocorria apesar de o Supremo Tribunal Federal já ter reconhecido a inconstitucionalidade de leis editadas pela União e pelos Estados a respeito da matéria, ressaltando se tratar de competência municipal. Em razão desse debate, o Procurador-Geral do Município Alfa solicitou que sua assessoria analisasse a possibilidade de o Município requerer a edição de uma súmula vinculante sobre a matéria, pois, em determinada relação processual, caso fosse reconhecida a inconstitucionalidade de lei similar, seria grande o prejuízo que seria causado à edilidade. À luz da sistemática vigente, é correto afirmar que o objetivo alvitrado pelo Procurador-Geral do Município','{"A": "não é possível, pois a súmula vinculante não pode ter por objeto a discussão de direito municipal.", "B": "é possível, o que deve ser feito incidentalmente ao curso do processo em que o Município Alfa é parte.", "C": "não é possível, pois somente os legitimados à deflagração do controle concentrado de constitucionalidade podem fazê-lo, mas é cabível a reclamação.", "D": "não é possível, pois a súmula vinculante deve ser editada em caráter abstrato, baseada em decisões pretéritas, estando dissociada de uma controvérsia atual.", "E": "é possível, sendo a proposição encaminhada ao Supremo Tribunal Federal caso o juízo competente reconheça a relevância da controvérsia para a relação processual."}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',34,'Direito Constitucional',null,'Um legitimado ingressou com ação direta de inconstitucionalidade contra a Lei nº X, do Estado Alfa, argumentando com a sua total incompatibilidade em relação à Constituição da República. Esse diploma normativo exigiu o preenchimento de certos requisitos, pela generalidade dos beneficiários, para a fruição de determinado benefício. Ao julgar o caso, o Supremo Tribunal Federal considerou que os requisitos previstos, apesar de serem compatíveis com a ordem constitucional, não poderiam ser exigidos de uma classe de beneficiários em potencial. Essa decisão teria eficácia contra todos e efeito vinculante em relação aos órgãos do Poder Judiciário e à Administração Pública federal, estadual e municipal. Considerando a técnica de decisão adotada, é correto afirmar que o Tribunal realizou uma','{"A": "declaração parcial de inconstitucionalidade sem redução de texto, que tem base legal.", "B": "interpretação conforme à Constituição, que tem base jurisprudencial, não legal.", "C": "restrição de sentido, com redução textual parcial, que tem base jurisprudencial e legal.", "D": "declaração de constitucionalidade parcial, com redução de sentido, que tem base legal.", "E": "declaração de nulidade parcial, com limitação de significantes, que tem base legal."}'::jsonb,'A',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',35,'Direito Constitucional',null,'João, estudante de direito, tinha muitas dúvidas em relação à conhecida classificação das formas de governo oferecida por Aristóteles. Após ampla digressão teórica, o Professor explicou corretamente a João que o referido pensador','{"A": "distinguia as formas de governo normais das anormais, o que decorria de um critério ético, baseado no atendimento ao interesse geral.", "B": "situava as formas de governo nos referenciais de democracia, teocracia e clerocracia, conforme o seu fundamento fosse o povo, a nobreza ou o clero.", "C": "lastreava as formas de governo direcionadas ao bem comum em referenciais de base axiológica, explicitados nos valores de honra, moderação e virtude.", "D": "concebia o governo de maneira monolítica, lastreado na vontade popular, o que caracterizava a democracia, sendo plúrimo o seu modo de exercício.", "E": "concebia duas formas de governo, que expressavam a concepção de república própria dos antigos, sendo dividida em república aristocrática e república democrática."}'::jsonb,'A',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',36,'Direito Constitucional',null,'Em razão de ampla mobilização popular, o Estado Alfa, com o objetivo de proteger as vítimas e as testemunhas de infrações penais, editou a Lei nº XX, a partir de projeto de lei de iniciativa parlamentar, estatuindo o sigilo no boletim de ocorrência e no inquérito policial no âmbito do referido ente federativo. Por entender que a Lei nº XX era flagrantemente prejudicial à sua atividade, a associação dos veículos de comunicação social solicitou que sua assessoria jurídica analisasse a compatibilidade desse diploma normativo com a ordem constitucional. A assessoria respondeu corretamente que a Lei nº XX é','{"A": "inconstitucional, por violar a liberdade de informação.", "B": "inconstitucional, pois está presente o vício de iniciativa.", "C": "constitucional, por se enquadrar no âmbito da competência legislativa residual dos Estados.", "D": "inconstitucional, por violar a competência privativa da União para legislar sobre processo penal.", "E": "constitucional, por se ajustar à competência concorrente entre a União e os Estados para legislar sobre matéria procedimental."}'::jsonb,'E',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',37,'Direito Constitucional',null,'Com o objetivo de incentivar a solidariedade social e zelar pela saúde coletiva, o Estado Alfa editou a Lei nº XX, determinando que as sociedades empresárias que explorem o serviço de telefonia em seu território insiram, nas faturas de consumo, mensagens de incentivo à doação de sangue. Irresignado com o teor da Lei nº XX, o Partido Político Delta ingressou com ação direta de inconstitucionalidade perante o Supremo Tribunal Federal, argumentando a incompatibilidade entre esse diploma normativo e a Constituição da República. À luz dessa narrativa, é correto afirmar que o referido Tribunal deve julgar o pedido','{"A": "procedente, considerando a evidente afronta à livre iniciativa e ao princípio da proporcionalidade.", "B": "procedente, considerando que a União figura como poder concedente nos contratos de concessão do serviço de telefonia.", "C": "procedente, considerando que compete privativamente à União legislar sobre seguridade social em suas distintas vertentes.", "D": "improcedente, considerando que a matéria é de competência comum entre a União, os Estados, o Distrito Federal e os Municípios.", "E": "improcedente, considerando que os Estados possuem competência concorrente com a União para legislar sobre proteção à saúde."}'::jsonb,'E',true,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',38,'Direito Constitucional',null,'Em razão de um grande escândalo de corrupção envolvendo autoridades do alto escalão do Estado Alfa, houve um debate no qual foi suscitada a impossibilidade de ser iniciado o processo penal em detrimento do Governador do Estado Alfa sem prévia autorização da estrutura legislativa competente. Considerando os balizamentos estabelecidos pela sistemática constitucional, é correto afirmar que a referida autorização é','{"A": "desnecessária, salvo se houver previsão expressa na Constituição do Estado Alfa.", "B": "necessária, por força do princípio da simetria, ainda que essa exigência não esteja expressa na Constituição Estadual.", "C": "necessária, o que decorre de previsão constitucional expressa, enquanto emanação do princípio da separação dos poderes.", "D": "desnecessária, pois a Constituição da República não contempla regra que autorize a previsão dessa exigência em relação ao Governador do Estado.", "E": "desnecessária, pois não há nenhuma situação em que o início do processo criminal esteja condicionado à autorização de órgão estranho ao Poder Judiciário."}'::jsonb,'D',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',39,'Direito Constitucional',null,'Ana nasceu em território turco, sendo filha de pai alemão e mãe francesa, os quais trabalhavam na embaixada brasileira localizada na Turquia. Após crescer estudando a cultura brasileira, pois recebia influência direta do emprego dos seus pais, e completar 18 anos, Ana decidiu que seguiria carreira política no Brasil. Ao decidir realizar esse sonho, consultou um advogado a respeito da sua nacionalidade, sendo-lhe corretamente informado que, à luz da ordem constitucional brasileira, ela é','{"A": "brasileira nata.", "B": "brasileira nata, desde que tenha sido registrada na embaixada brasileira da Turquia.", "C": "estrangeira, mas pode optar pela nacionalidade brasileira caso venha a residir no Brasil.", "D": "estrangeira, mas pode se naturalizar brasileira caso sejam preenchidos os requisitos previstos em lei ordinária.", "E": "estrangeira, mas pode se naturalizar brasileira, o que pressupõe o requisito indispensável de que resida quinze anos interruptos no Brasil e não tenha condenação penal."}'::jsonb,'D',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',40,'Direito Constitucional',null,'João, marido de Maria, governadora do Estado Beta, almejava concorrer ao cargo eletivo de Deputado Estadual, no mesmo Estado, nas eleições a serem realizadas no ano seguinte. Para sua tristeza, Maria faleceu no ano da eleição. À luz da sistemática constitucional, é correto afirmar que João','{"A": "está inelegível para o cargo almejado, qualquer que seja o mês de falecimento de Maria.", "B": "está elegível para o cargo almejado, pois a ordem constitucional não alberga inelegibilidades reflexas, apenas inelegibilidades pessoais.", "C": "somente está inelegível para o cargo almejado caso Maria tenha falecido nos seis meses anteriores à eleição.", "D": "está inelegível para o cargo almejado, salvo se Maria, como Vice-Governadora, sucedeu o Governador no curso do mandato.", "E": "está elegível para o cargo almejado, independente do falecimento de Maria, considerando que almeja ocupar cargo no Poder Legislativo, não no Executivo."}'::jsonb,'C',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',41,'Direito Constitucional',null,'Após amplo levantamento, a Secretaria de Patrimônio do Estado Alfa constatou a existência de uma larga faixa de terra, ao sul do seu território, que jamais recebera qualquer destinação pelo Poder Público ou integrara o patrimônio de um particular. Essa faixa de terra, ademais, era considerada indispensável, pelos biólogos, à preservação de um ecossistema próximo. Considerando as dificuldades de fluxo de caixa do Estado Alfa, a referida Secretaria sugeriu ao Governador do Estado a alienação dessa faixa de terra. É correto afirmar que a sugestão apresentada','{"A": "não pode ser acolhida por se tratar de terra pertencente à União.", "B": "não pode ser acolhida, por se tratar de terra pertencente aos Municípios.", "C": "pode ser acolhida, o que pressupõe prévia autorização da Assembleia Legislativa.", "D": "pode ser acolhida, o que decorre do poder de gestão do Chefe do Poder Executivo, salvo se a faixa de terra tiver sido declarada como área de preservação ambiental.", "E": "pode ser acolhida, o que decorre do poder de gestão do Chefe do Poder Executivo, salvo se a indispensabilidade à proteção ambiental tiver sido reconhecida em lei da União."}'::jsonb,'A',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',42,'Direito Constitucional',null,'A Constituição do Estado Alfa, com o objetivo de ampliar os níveis de controle popular sobre as decisões políticas do Chefe do Poder Executivo, foi reformada e passou a dispor que todas as nomeações para secretarias de governo, no âmbito do Estado Alfa e dos Municípios situados em seu território, deveriam ser previamente aprovadas pelo Poder Legislativo, vale dizer, pela Assembleia Legislativa ou pela Câmara Municipal, conforme o caso. Ao tomar conhecimento da reforma promovida na Constituição Estadual, o Prefeito do Município Beta determinou que sua assessoria analisasse a compatibilidade da reforma com a Constituição da República, sendo-lhe corretamente informado que ela é','{"A": "constitucional, já que a Constituição Estadual é a sedes materiae para a disciplina do exercício do poder no âmbito estadual e municipal.", "B": "constitucional, já que a Constituição Estadual se limita a integrar a eficácia de norma programática já prevista na Constituição da República.", "C": "constitucional apenas em relação ao Estado Alfa, mas inconstitucional ao estender esse comando aos Municípios, isto por violar a sua autonomia.", "D": "inconstitucional, já que a Constituição da República limita a chancela, pelo Poder Legislativo, à aprovação dos ocupantes dos órgãos de cúpula da Administração Indireta.", "E": "inconstitucional, já que a reforma afronta a separação dos poderes ao estabelecer indevida ingerência do Poder Legislativo em atividade própria do Executivo."}'::jsonb,'E',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',43,'Direito Constitucional',null,'Mariana, servidora pública ocupante de cargo de provimento efetivo no âmbito do Estado Alfa, que era organizado em carreira, subdividida em três classes, cada qual contando com cinco padrões, tomou ciência da recente aprovação da Lei estadual nº X, que determinava a aplicação da sistemática de subsídios aos servidores que se encontravam na situação dela. Em razão da edição da Lei estadual nº X, Mariana consultou o seu advogado a respeito da compatibilidade desse diploma normativo com a Constituição da República, sendo-lhe corretamente respondido que ele é','{"A": "constitucional, considerando que compete a cada ente federativo, no exercício de sua autonomia política, definir os cargos efetivos, eletivos ou em comissão, que serão alcançados pela sistemática de subsídios.", "B": "inconstitucional, pois os cargos suscetíveis de enquadramento na sistemática de subsídios estão elencados em numerus clausus em lei complementar federal, não sendo o caso do cargo ocupado por Mariana.", "C": "constitucional, pois a sistemática de subsídios pode ser estendida aos servidores em situação similar à de Mariana, sendo vedado o acréscimo de qualquer outro valor remuneratório a essa parcela única.", "D": "inconstitucional, pois a sistemática de subsídios somente pode ser aplicada ao membro de Poder, ao detentor de mandato eletivo, aos Ministros e aos Secretários.", "E": "constitucional, considerando que passou a ser cogente a aplicação da sistemática de subsídios à generalidade dos servidores públicos organizados em carreira."}'::jsonb,'C',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',44,'Direito Constitucional',null,'Os servidores públicos do Estado Sigma realizaram uma grande mobilização visando a alterar a sistemática previdenciária que lhes era aplicável. O principal ponto de insatisfação consistia na sua atual vinculação ao regime geral de previdência social, o que era considerado muito desvantajoso, a começar pelo teto dos benefícios pagos nesse regime. Sensibilizado com a manifestação, e por considerar injusto o tratamento dispensado aos servidores, o Deputado Estadual João solicitou que sua assessoria analisasse a forma pela qual poderia ser instituído um regime próprio de previdência social (RPPS) no Estado Alfa, sendo-lhe corretamente informado que','{"A": "a instituição de RPPS exige a apresentação de projeto de lei de iniciativa do Chefe do Poder Executivo e pressupõe a demonstração de superávit no fluxo de receitas e despesas.", "B": "a instituição de RPPS pressupõe projeto de iniciativa do Chefe do Poder Executivo, que só pode ser apresentado, em razão de norma constitucional de transição, até o fim de 2023.", "C": "a instituição de RPPS pressupõe a edição de lei complementar estadual, que deve seguir os balizamentos estabelecidos pela lei nacional que trata da temática.", "D": "a instituição de RPPS somente pode ser realizada a partir de reforma da Constituição Estadual, observado o poder de iniciativa nela estabelecido.", "E": "é vedada a instituição de RPPS."}'::jsonb,'E',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',45,'Direito Constitucional',null,'Joana, oficial médica da Polícia Militar do Estado Alfa, almejava se inscrever em um concurso público para o provimento de cargos de médico no Município Beta. Ao se inteirar da possibilidade de cumular ambos os cargos, concluiu corretamente que','{"A": "não poderá cumular os cargos, já que um deles tem natureza civil, enquanto o outro é militar.", "B": "não poderá cumular os cargos, já que o vínculo seria estabelecido nos entes federativos distintos.", "C": "poderá cumular os cargos, pois a vedação constitucional à cumulação somente é aplicada no mesmo nível federativo, não em níveis diversos.", "D": "poderá cumular os cargos, com prevalência da atividade militar, sendo a remuneração de cada qual cotejada com o respectivo teto remuneratório.", "E": "poderá cumular os cargos, pois são privativos de profissionais de saúde, com profissões regulamentadas, mas a soma da remuneração não pode superar o teto remuneratório."}'::jsonb,'D',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',46,'Direito Constitucional',null,'Após ampla mobilização dos Deputados Estaduais, a Constituição do Estado Alfa foi reformada, passando a dispor sobre a competência das Comissões da Assembleia Legislativa para a colheita de manifestações de pessoas que possam contribuir com suas atividades. Com esse objetivo, foi autorizada a convocação das seguintes autoridades: (1) Secretários de Estado; (2) Procurador-Geral do Estado; (3) Procurador-Geral de Justiça; e (4) Presidentes de autarquias e de fundações com personalidade jurídica de direito público. Acresça-se que o não atendimento à convocação caracterizaria infração político-administrativa. Irresignado com o teor da reforma, o Partido Político Delta consultou sua assessoria a respeito da compatibilidade desse comando normativo com a Constituição da República, sendo-lhe corretamente respondido que','{"A": "somente é compatível com a ordem constitucional a convocação das autoridades referidas em 1, 3 e 4.", "B": "somente é compatível com a ordem constitucional a convocação das autoridades referidas em 2, 3 e 4.", "C": "somente é compatível com a ordem constitucional a convocação das autoridades referidas em 2 e 3.", "D": "somente é compatível com a ordem constitucional a convocação das autoridades referidas em 1 e 2.", "E": "é compatível com a ordem constitucional a convocação das autoridades referidas em 1, 2, 3 e 4."}'::jsonb,'D',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',47,'Direito Constitucional',null,'O Presidente da República editou a Medida Provisória nº X, que tem por objetivo a disponibilização de recursos para a realização de despesas não previstas na lei orçamentária anual, o que decorreu da existência de uma situação imprevista, em que se decidiu pelo desenvolvimento de determinada política pública de interesse da coletividade. À luz da sistemática constitucional, é correto afirmar que a Medida Provisória nº X é','{"A": "constitucional, pois ela dispôs sobre créditos suplementares.", "B": "inconstitucional, pois ela dispôs sobre créditos especiais, o que é vedado.", "C": "inconstitucional, pois a abertura de créditos extraordinários exige a edição de lei em sentido formal.", "D": "inconstitucional, pois a medida provisória não pode dispor sobre nenhuma espécie de crédito adicional.", "E": "constitucional, considerando que a abertura de créditos extraordinários deve ser realizada por medida provisória."}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',48,'Direito Constitucional',null,'Maria, Deputada Estadual, constatou que o Governador do Estado editou um decreto que, ao seu ver, não só ultrapassava os balizamentos oferecidos pela Lei Complementar nº X como a afrontava diretamente. Irresignada com esse ato, que reputava flagrantemente dissonante da separação dos poderes, Maria solicitou que sua assessoria analisasse a medida a ser adotada, no âmbito da Assembleia Legislativa, em relação ao ato praticado pelo Governador. A assessoria respondeu corretamente, à luz da sistemática estabelecida na Constituição da República, que a Assembleia Legislativa pode','{"A": "revogar o decreto, a partir do reconhecimento de sua inconstitucionalidade, por afronta à separação dos poderes.", "B": "impedir a efetividade do decreto, embora não possa incursionar no âmbito de sua validade e eficácia.", "C": "reconhecer a incompatibilidade do decreto com a Lei Complementar nº X, sustando-o.", "D": "declarar a inconstitucionalidade do decreto, o que importa no reconhecimento de sua nulidade.", "E": "impetrar mandado de segurança, para que o Poder Judiciário declare a ilegalidade do ato."}'::jsonb,'C',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',49,'Direito Constitucional',null,'Joana, brasileira nata, que era funcionária contratada do Ministério das Relações Exteriores do País Alfa, recebeu, de seu superior hierárquico, a incumbência de identificar, à luz da ordem constitucional brasileira, o que deve ser feito para que o representante diplomático do País Alfa possa atuar no território da República Federativa do Brasil. Após percuciente análise, Joana concluiu corretamente que o referido representante diplomático deve','{"A": "receber o exequatur do Presidente da República.", "B": "ser aceito pelo Presidente da República, com posterior referendo do Senado Federal.", "C": "ser acreditado pelo Presidente da República, independente de manifestação do Poder Legislativo.", "D": "ser necessariamente aceito pela República Federativa do Brasil, por ser representante do Estado Alfa.", "E": "ser aprovado pelo Senado Federal e, uma vez aceito, receber a carta de recepção do Presidente da República."}'::jsonb,'C',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',50,'Direito Constitucional',null,'Pedro, Deputado Estadual, no mês imediatamente anterior à posse nesse cargo, aceitara atuar como diretor executivo de uma sociedade empresária concessionária de serviço público de transporte intermunicipal, vínculo este que cessou no dia anterior à sua posse. Alguns meses depois, em um debate envolvendo projeto de lei que versava sobre a agência reguladora estadual, que deveria atuar no âmbito da generalidade dos serviços públicos desse nível federativo, Mário, também Deputado Estadual, informou que Pedro não tinha isenção para participar do debate, tornando pública a referida informação. À luz da sistemática estabelecida na Constituição da República, é correto afirmar que a conduta de Pedro','{"A": "não é juridicamente ilícita.", "B": "é ilícita e deve acarretar, como consequência, a perda do mandato.", "C": "será lícita ou ilícita conforme dispuser a Constituição Estadual e o regimento interno da Assembleia Legislativa.", "D": "é ilícita, mas, com a posse, ocorreu a preclusão de qualquer medida que poderia ser adotada em seu desfavor.", "E": "é lícita, já que as vedações incidentes sobre os Deputados Estaduais somente se tornam operativas após a posse."}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',51,'Direito Constitucional',null,'Um assessor do Presidente da República o informou a respeito do recebimento de relatórios de diversos Ministros de estado, apontando a existência de inúmeros cargos vagos em suas estruturas e pela existência de outros cargos que se encontravam ocupados e se mostravam desnecessários. Por tal razão, propuseram a extinção desses cargos. O assessor informou corretamente ao Presidente da República que ele, caso acolha os argumentos apresentados, deve','{"A": "propor ao Poder Legislativo, com base no princípio da paridade das formas, a extinção desses cargos, sendo demitidos os servidores estáveis que estejam ocupando os cargos extintos.", "B": "extinguir os cargos vagos e declarar a desnecessidade dos cargos ocupados, sendo postos em disponibilidade, neste último caso, os servidores estáveis que os ocupem.", "C": "propor ao Poder Legislativo a extinção dos cargos vagos e aguardar que os cargos atualmente ocupados fiquem vagos, para que seja proposta a sua extinção.", "D": "declarar a desnecessidade dos cargos vagos e dos cargos ocupados, o que impedirá novas nomeações, até que sejam extintos pelo Poder Legislativo.", "E": "extinguir os cargos vagos e os cargos ocupados, sendo postos em disponibilidade, neste último caso, todos os servidores que os ocupem."}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',52,'Direito Constitucional',null,'O Presidente do Tribunal de Justiça do Estado Alfa foi informado por sua assessoria que já era o momento de serem adotadas as providências relacionadas ao orçamento do ano vindouro, uma vez que o denominado “ciclo orçamentário”, que abrange o conjunto de medidas que culminarão com a elaboração da lei orçamentária anual do próximo exercício financeiro, estava prestes a se iniciar. Em relação às medidas relacionadas ao referido “ciclo orçamentário”, a assessoria respondeu corretamente que','{"A": "o Tribunal de Justiça deve estipular, juntamente com os demais Poderes, na lei de diretrizes orçamentárias, os limites de sua proposta orçamentária.", "B": "a proposta orçamentária do Tribunal de Justiça deve ser submetida ao Poder Legislativo no prazo estabelecido pela ordem constitucional, observados os limites estabelecidos pela lei de diretrizes orçamentárias.", "C": "a proposta orçamentária será encaminhada, pelo Tribunal de Justiça, ao Poder Executivo, que a compatibilizará com as propostas das estruturas estatais de poder, de modo a assegurar o equilíbrio orçamentário.", "D": "caso o Tribunal de Justiça não encaminhe sua proposta orçamentária no prazo estabelecido pela lei de diretrizes orçamentárias, o Poder Legislativo irá considerar os valores da lei orçamentária vigente, corrigidos monetariamente.", "E": "a proposta orçamentária do Tribunal de Justiça deve observar a desvalorização da moeda desde a aprovação da última lei orçamentária, devendo ser encaminhada ao Poder Legislativo após manifestação da Secretaria de Estado competente."}'::jsonb,'A',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',53,'Direito Constitucional',null,'O Presidente da Assembleia Legislativo do Estado Alfa praticou ato que, ao ver do Deputado Estadual João, era manifestamente contrário à Constituição Estadual e ao Regimento Interno da Casa Legislativa, o que o levou a impetrar mandado de segurança perante o Órgão Especial do Tribunal de Justiça. A ordem, no entanto, foi denegada com base em um argumento manifestamente contrário à Constituição da República. À luz da sistemática constitucional, é correto afirmar que, em sendo preenchidos os demais requisitos exigidos','{"A": "não é cabível a interposição de recurso a nenhum tribunal nacional, considerando que as normas discutidas na impetração têm natureza estadual.", "B": "pode ser interposto recurso especial, a ser processado e julgado pelo Superior Tribunal de Justiça.", "C": "pode ser interposto recurso extraordinário, a ser processado e julgado pelo Supremo Tribunal Federal.", "D": "pode ser interposto recurso ordinário a ser processado e julgado pelo Superior Tribunal de Justiça.", "E": "pode ser impetrado mandado de segurança perante o Supremo Tribunal Federal."}'::jsonb,'D',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',54,'Direito Constitucional',null,'Um grupo armado, formado por agentes públicos vinculados ao Estado Alfa, desferiu disparos de arma de fogo, que foram a causa eficiente da morte de dezena de pessoas, sendo todas elas familiares de indivíduos alegadamente envolvidos com a criminalidade. Por entenderem que as forças de segurança do Estado estariam possivelmente mancomunadas com os autores do ilícito, não realizando a apuração da forma devida, pessoas próximas às vítimas decidiram consultar um advogado a respeito da possibilidade de a apuração ser deslocada para a Justiça Federal. O advogado respondeu corretamente que','{"A": "é possível o deslocamento de competência, o que pode ser requerido por legítimo interessado ao Tribunal Regional Federal competente.", "B": "é possível o deslocamento de competência, o que deve ser requerido por legitimado específico e deferido pelo tribunal nacional competente.", "C": "ocorreu a perpetuatio jurisdictionis, não sendo possível a alteração de competência após a prática do ilícito, sob pena de configuração de um juízo de exceção.", "D": "é possível o deslocamento de competência, desde que isto seja deferido pelo tribunal nacional competente, mas apenas na fase processual, não durante o inquérito.", "E": "é possível o deslocamento de competência, desde que demonstrada, perante o Supremo Tribunal Federal, a existência de causa de suspeição ou impedimento."}'::jsonb,'B',true,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',55,'Direito Constitucional',null,'Maria logrou êxito em ser aprovada no processo seletivo destinado ao preenchimento das vagas no Mestrado em Odontologia oferecido pela Universidade Estadual XX. Ao comparecer, no dia e no local indicados, para a realização de matrícula, foi surpreendida com a informação de que deveria efetuar o pagamento da taxa de matrícula. Irresignada com o teor dessa informação, consultou o seu advogado a respeito da correção dessa cobrança à luz da Constituição da República, sendo-lhe corretamente informado que a cobrança estava','{"A": "certa, considerando a autonomia universitária para definir que atividades acadêmicas podem ensejar a referida cobrança.", "B": "errada, considerando a necessária gratuidade do ensino público a nível de pós-graduação, lato sensu ou stricto sensu.", "C": "errada, considerando a gratuidade do ensino público nos distintos níveis da educação formal com graus reconhecidos.", "D": "certa, considerando que a gratuidade do ensino público somente é impositiva até o nível de graduação.", "E": "errada, desde que Maria demonstre a sua hipossuficiência econômica, o que lhe assegura a gratuidade."}'::jsonb,'C',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',56,'Direito Constitucional',null,'João, pessoa hipossuficiente, necessitava de uma intervenção cirúrgica para restabelecer o alinhamento de sua coluna e evitar a compressão setorial de alguns nervos, o que vinha lhe causando dores insuportáveis. Após uma exaustiva procura de vaga para a operação em diversos hospitais públicos, obtendo sempre respostas negativas, João decidiu ingressar com uma ação judicial em face do ente competente, visando a compeli-lo a realizar a cirurgia, que se afigurava urgente. À luz da sistemática constitucional, a ação deve ser ajuizada em face','{"A": "da União, considerando a sua posição de mantenedora do sistema brasileiro de saúde.", "B": "do Município no qual João reside, considerando a predominância do interesse local.", "C": "do Estado no qual João reside, considerando a sua obrigação primária de atender aos casos mais complexos.", "D": "do Município no qual João reside, do Estado no qual João reside ou da União, em conjunto ou isoladamente.", "E": "do ente federativo cuja legislação contemple a obrigação de ser realizada a cirurgia de João em seu sistema de saúde."}'::jsonb,'D',true,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',57,'Direito Constitucional',null,'A Lei federal nº X dispôs que as pessoas jurídicas que se encontrassem em débito com o sistema de seguridade social, observado o período de endividamento ali estabelecido, estariam impossibilitadas de celebrar contratos com o Poder Público dos distintos níveis federativos. Em razão de grave crise econômica, que aumentou o nível de endividamento das pessoas jurídicas, sobreveio a Lei federal nº Y, que não só suprimiu a vedação como determinou que seria assegurado a essas pessoas jurídicas o recebimento dos incentivos fiscais e creditícios que indicava. Irresignado com o teor da Lei federal nº Y, o Partido Político Alfa, com representação no Congresso Nacional, consultou o seu advogado a respeito da constitucionalidade deste diploma normativo, sendo-lhe corretamente respondido que ele era','{"A": "constitucional, por integrar a eficácia do princípio do livre desenvolvimento sustentável.", "B": "inconstitucional, pois contrariou determinação constitucional, cuja eficácia foi integrada pela Lei federal nº X.", "C": "constitucional, pois se limitou a afastar a incidência das “sanções políticas” ilicitamente estabelecidas pela Lei federal nº X.", "D": "constitucional, pois a União, conforme a sua valoração política, tem a opção de adotar tanto a sistemática da Lei federal nº X como a da Lei nº Y.", "E": "inconstitucional, por afrontar o princípio constitucional da isonomia, na parte em que direcionou incentivos fiscais e creditícios apenas às pessoas jurídicas em débito."}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',58,'Direito Constitucional',null,'A Constituição do Estado Alfa foi objeto de emenda em relação à disciplina das competências do Tribunal de Contas Estadual. De acordo com a disciplina estabelecida pela emenda, as contas de governo apresentadas pelos chefes dos poderes municipais seriam julgadas pelas Câmaras Municipais, considerando o parecer prévio do Tribunal de Contas, que somente deixaria de prevalecer por decisão de dois terços dos membros dessas Câmaras. À luz da sistemática estabelecida na Constituição da República, é correto afirmar que a referida emenda é','{"A": "materialmente constitucional, pois reproduz comandos já veiculados pela Constituição da República.", "B": "materialmente inconstitucional, pois as Câmaras Municipais somente têm competência para julgar as contas do Chefe do Poder Executivo.", "C": "formalmente inconstitucional, pois, em razão da autonomia dos Municípios, a matéria deveria ser disciplinada nas leis orgânicas municipais.", "D": "formal e materialmente constitucional, pois cabe às Constituições estaduais veicular as regras e os princípios aos quais estão vinculados os Municípios.", "E": "materialmente inconstitucional, pois fere a autonomia municipal o quórum qualificado de votação para que deixe de prevalecer o parecer do Tribunal de Contas."}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',59,'Direito Constitucional',null,'Em razão do crescimento do número de roubos, mediante o emprego de arma de fogo, no território do Estado Alfa, foi editada a Lei estadual nº X. De acordo com esse diploma normativo, que foi objeto de severas críticas por parte da entidade representativa das instituições financeiras, era obrigatória, sob pena de multa, a instalação de equipamentos de segurança nas agências bancárias. Além das críticas, foram obtidos diversos provimentos jurisdicionais nos quais era desautorizada a aplicação da Lei estadual nº X sob o argumento de sua inconstitucionalidade. À luz dessa narrativa, é correto afirmar que a Lei estadual nº X é','{"A": "constitucional, porque o Estado pode legislar em matérias afetas à segurança pública.", "B": "inconstitucional, por afrontar a competência privativa da União para legislar sobre segurança pública.", "C": "inconstitucional, por afrontar a competência dos Municípios para legislar sobre assuntos de interesse local.", "D": "constitucional, considerando que as regras afetas às construções edilícias devem ser uniformizadas em lei estadual.", "E": "não pode ser objeto de ação ajuizada perante o Supremo Tribunal Federal cujo pedido seja o reconhecimento de sua constitucionalidade."}'::jsonb,'A',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',60,'Direito Constitucional',null,'Em determinado exercício financeiro, Josué, Deputado Estadual, constatou que o Governador do Estado do Maranhão, até o dia 31 de março, ainda não tinha apresentado as contas concernentes ao exercício pretérito. Ao constatar essa omissão, Josué consultou sua assessoria a respeito das medidas passíveis de serem adotadas pela Assembleia Legislativa do Estado do Maranhão em relação a esse proceder. A assessoria respondeu corretamente, à luz da Constituição Estadual, que a Assembleia Legislativa','{"A": "deve proceder à tomada de contas.", "B": "pode solicitar que o Tribunal de Contas proceda à tomada de contas especial.", "C": "deve requisitar que o Tribunal de Contas proceda à tomada de contas especial.", "D": "deve aguardar o exaurimento do prazo constitucional e, persistindo a omissão, proceder à tomada de contas.", "E": "deve aguardar o término do exercício financeiro e, persistindo a omissão, proceder à tomada de contas."}'::jsonb,'D',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno')
